-- Auto-generated from the GEDCOM export embedded in public/html/main-treee.html
-- Source: Family Echo export, "THERAMPU FAMILY", founder Itty Cheriyan
-- Run this whole file once in the Supabase SQL editor (Project > SQL Editor > New query).

create extension if not exists pgcrypto;

create table if not exists public.family_members (
  id uuid primary key default gen_random_uuid(),
  gedcom_ref text unique,
  given_name text not null,
  surname text,
  married_name text,
  display_name text not null,
  gender text check (gender in ('M', 'F')),
  birth_year int,
  birth_date_text text,
  birth_place text,
  death_year int,
  death_date_text text,
  death_place text,
  marriage_year int,
  father_id uuid references public.family_members(id) on delete set null deferrable initially deferred,
  mother_id uuid references public.family_members(id) on delete set null deferrable initially deferred,
  spouse_id uuid references public.family_members(id) on delete set null deferrable initially deferred,
  photo_url text,
  bio text,
  created_at timestamptz not null default now()
);

create index if not exists family_members_father_id_idx on public.family_members(father_id);
create index if not exists family_members_mother_id_idx on public.family_members(mother_id);
create index if not exists family_members_spouse_id_idx on public.family_members(spouse_id);

alter table public.family_members enable row level security;

drop policy if exists "Public read access" on public.family_members;
create policy "Public read access" on public.family_members
  for select using (true);

truncate table public.family_members cascade;

